from collections import defaultdict

def find_regions_and_intruders(grid, threshold=5):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    visited = [[False] * cols for _ in range(rows)]
    regions = []

    def bfs(start_r, start_c):
        color = grid[start_r][start_c]
        cells = [(start_r, start_c)]
        stack = [(start_r, start_c)]

        while stack:
            r, c = stack.pop()
            if visited[r][c]:
                continue
            visited[r][c] = True

            dr = [-1, 1, 0, 0]
            dc = [0, 0, -1, 1]

            for i in range(4):
                nr, nc = r + dr[i], c + dc[i]
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                    if grid[nr][nc] == color:
                        cells.append((nr, nc))
                        stack.append((nr, nc))

        return cells

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                cells = bfs(r, c)
                count_color = defaultdict(int)
                for cr, cc in cells:
                    count_color[grid[cr][cc]] += 1

                most_common = max(count_color.keys(), key=lambda k: count_color[k])
                main_value = count_color[most_common]
                intruders = [(cr, cc) for cr, cc in cells if grid[cr][cc] != most_common]

                if intruders:
                    regions.append({
                        'primary': most_common,
                        'count': main_value,
                        'cells': cells,
                        'intruders': intruders,
                        'intruder_count': len(intruders),
                        'intruder_values': set(grid[cr][cc] for cr, cc in intruders)
                    })

    return regions

