def find_isolated_cells(grid, target_value):
    """Find cells with target_value that have no neighbors of same value"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    isolated = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_value:
                # Count neighbors with same value
                neighbors_same = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == target_value:
                            neighbors_same += 1

                if neighbors_same == 0:
                    isolated.append((r, c))

    return isolated

