def get_expected_value(grid, r, c, radius=2):
    rows = len(grid)
    cols = len(grid[0])

    # Collect all neighboring values within radius
    values = defaultdict(int)
    total = 0

    for dr in range(-radius, radius+1):
        for dc in range(-radius, radius+1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                values[grid[nr][nc]] += 1
                total += 1

    if total == 0:
        return grid[r][c]

    most_common = max(values.keys(), key=lambda k: values[k])
    return most_common

