def fix_grid(grid):
    rows = len(grid)
    cols = len(grid[0])

    # First pass: identify cells that are in uniform regions but have wrong value
    fixed = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            current = grid[r][c]

            # Look at neighbors and find the dominant one
            # Use a weighted average where closer cells count more
            weights = {}
            for dr in range(-4, 5):
                for dc in range(-4, 5):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        d2 = dr**2 + dc**2
                        weight = 1.0 / (d2 + 1)
                        weights[grid[nr][nc]] = weights.get(grid[nr][nc], 0) + weight

            # Find the most weighted color
            best_color = max(weights.keys(), key=lambda k: weights[k])

            # If current doesn't match best, consider fixing it
            # But don't fix everything - only obvious errors
            if current != best_color:
                # Check if we're inside a large region
                is_largest_region = False
                region_counts = defaultdict(int)
                for dr in range(-5, 6):
                    for dc in range(-5, 6):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            region_counts[grid[nr][nc]] += 1

                dominant = max(region_counts.keys(), key=lambda k: region_counts[k])
                if region_counts[dominant] > 10:  # In a big region
                    is_largest_region = True

                if is_largest_region and current not in [0, 2, 3, 7, 8]:
                    fixed[r][c] = best_color

    return fixed

