    """Fix pixels that clearly don't belong to their dominant region"""
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find all regions first by simple flood fill
    visited = [[False] * cols for _ in range(rows)]
    all_regions = []  # (color, center_x, center_y, size)

    def flood_fill(sr, sc):
        color = grid[sr][sc]
        region_cells = [(sr, sc)]
        stack = [(sr, sc)]

        while stack:
            r, c = stack.pop()
            if visited[r][c]:
                continue
            visited[r][c] = True

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                    if grid[nr][nc] == color:
                        region_cells.append((nr, nc))
                        stack.append((nr, nc))

        return region_cells

    # Create regions map
    cell_region = {}  # (r,c) -> (region_id, color)
    region_info = {}  # region_id -> (color, cells)

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                cells = flood_fill(r, c)
                reg_id = len(region_info)
                region_info[reg_id] = {'color': cells[0][1], 'cells': cells}
                for cr, cc in cells:
                    cell_region[(cr, cc)] = (reg_id, cells[0][1])

    # Now check for errors: cells whose local neighborhood suggests different region
    for r in range(rows):
        for c in range(cols):
            current_color = grid[r][c]

            # Get dominant color in expanded window
            dom = get_dominant_color_in_window(grid, r, c, base_radius)

            # If dominant differs from current, it might be an error
            if dom != current_color:
                # Count how many neighbors have the dominant color
                neighbor_count = 0
                total_neighbors = 0
                for dr in range(-base_radius, base_radius+1):
                    for dc in range(-base_radius, base_radius+1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neighbor_count += (1 if grid[nr][nc] == dom else 0)
                            total_neighbors += 1

                ratio = neighbor_count / max(total_neighbors, 1)

                # Only fix if strong evidence
                if ratio > 0.7:
                    result[r][c] = dom

    return result

