    def bfs_component(start_r, start_c):
        component = []
        queue = [(start_r, start_c)]
        while queue:
            r, c = queue.pop(0)
            if (r, c) in visited or grid[r][c] != grid[start_r][start_c]:
                continue
            visited.add((r, c))
            component.append((r, c, grid[r][c]))

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == grid[r][c]:
                    queue.append((nr, nc))

        return component

